<template>
    <div>
        <div class="app-content content"> 
        <div class="content-wrapper">
            <div class="content-header row">
                <div class="content-header-left col-12 mb-1 mt-0">
                    <div class="row breadcrumbs-top">
                        <div class="col-sm-9"> 
                            <div class="breadcrumb-wrapper col-9">
                                <ol class="breadcrumb p-0 mb-0">
                                   <li class="breadcrumb-item"><router-link :to="{ path: '/' }"><i class="bx bx-home-alt"></i></router-link>
                                    </li>
                                    <li class="breadcrumb-item active"> Wings
                                    </li>
                                     
                                </ol> 
                            </div>
                        </div>
                        <div class=" col-sm-3"> 
                            <a class="btn btn-primary add-btn" @click="show_pop()" > <i class="bx bx-add-alt"></i>New Wing </a>  
                        </div> 
                    </div>
                </div>
            </div> 
            <div class="content-body">
                <!-- Zero configuration table -->
                <section id="basic-datatable">
                    <div class="row">
                        <div class="col-12">
                            <div class="card"> 
                                <div class="card-content">
                                    <div class="card-body card-dashboard"> 
                                        <div class="row">
                                            <div class="col-lg-12">
                                            <div class="card">
                                                
                                                <table class="tablesaw table-striped table-hover table-bordered table" data-tablesaw-mode="columntoggle">
                                                    <thead>
                                                        <tr>
                                                        <th scope="col">SL</th>
                                                        <th scope="col">Department</th>
                                                        <th scope="col">WINGS HEAD NAME</th>
                                                        <th scope="col">SCREEN NAME</th>
                                                        <th scope="col">ACTION</th>
                                                        </tr>
                                                    </thead>
                                                    <tbody>
                                                        <tr v-for="(row, index) in WingsItems" :key="row.id"> 
                                                            <th scope="col"> {{ index + 1 }}</th> 
                                                            <th scope="col"> {{ row.deptjoin ? row.deptjoin.name : 'N/A' }} </th> 
                                                            <th scope="col"> 
                                                                <div v-if="!row.userjoin" > 
                                                                    <div  class="form-group">
                                                                        <label for="Profession">Assign wing head</label>
                                                                            <div class="controls">
                                                                                <select class="form-control" v-model="userChang.id"  v-on:change="changeUser(row.id)" id="users-list-verified" >
                                                                                    <option value="">Select One</option>
                                                                                    <option v-for="row in WingsUser"  :key="row.id" :value="row.id" >
                                                                                    {{ row.name }}
                                                                                    </option>
                                                                                </select>
                                                                        </div>
                                                                    </div> 
                                                                </div>  
                                                            {{ row.userjoin ? row.userjoin.name : ' ' }} </th>
                                                            <th scope="col"> {{ row.wing_title }}</th>
                                                            <th scope="col"> 
                                                                <div class="dropup">
                                                                    <span class="bx bx-dots-vertical-rounded font-medium-3 dropdown-toggle nav-hide-arrow cursor-pointer" data-toggle="dropdown" aria-haspopup="true" aria-expanded="false" role="menu">
                                                                    </span>
                                                                    <div class="dropdown-menu dropdown-menu-right">
                                                                        <router-link class="dropdown-item" :to="{ path: '/edit_wing/'+row.id }"><i class="bx bx-edit-alt mr-1"></i> Edit </router-link>
                                                                        <a class="dropdown-item" @click="delete_wing(row.id)"><i class="bx bx-trash mr-1"></i>Delete</a>
                                                                    </div>
                                                                </div> 
                                                            </th>
                                                        </tr> 
                                                    </tbody>
                                                </table>
                                               
                                                <div class="content-header row">
                                                    <div class="content-header-left col-12 mb-1 mt-0">
                                                        <div class="row breadcrumbs-top">
                                                            <div class="col-sm-9"> 
                                                                EMPLOYEE USER
                                                            </div>
                                                            <div class=" col-sm-3"> 
                                                                <router-link class="btn btn-primary add-btn" :to="{ path: '/new_user' }"> <i class="bx bx-add-alt"></i> New user </router-link>
                                                                <!-- <a class="btn btn-primary add-btn" @click="show_pop()" > <i class="bx bx-add-alt"></i>New Wing </a>   -->
                                                            </div> 
                                                        </div>
                                                    </div>
                                                </div> 
                                                <table class="tablesaw table-striped table-hover table-bordered table" data-tablesaw-mode="columntoggle">
                                                    <thead>
                                                        <tr>
                                                            <th scope="col">SL</th>
                                                            <th scope="col">WINGS HEAD NAME</th>
                                                            <th scope="col">EMPLOYEE ID</th>
                                                            <th scope="col">SCREEN NAME</th>
                                                            <th scope="col">Action</th>
                                                        </tr>
                                                    </thead>
                                                    <tbody>
                                                        <tr v-for="(row, index) in employeeItem" :key="row.id" >
                                                            <th scope="col">{{ index + 1 }}</th>
                                                            <th scope="col">
                                                                {{ row.wingjoin ?  row.wingjoin.wing_title : '' }}
                                                            </th>
                                                            <th scope="col">{{ row.email }}</th>
                                                            <th scope="col">{{ row.name }}</th>
                                                            <th scope="col">
                                                                <div class="dropup">
                                                                    <span class="bx bx-dots-vertical-rounded font-medium-3 dropdown-toggle nav-hide-arrow cursor-pointer" data-toggle="dropdown" aria-haspopup="true" aria-expanded="false" role="menu">
                                                                    </span>
                                                                    <div class="dropdown-menu dropdown-menu-right">
                                                                        <router-link class="dropdown-item" :to="{ path: '/edit_user/'+row.id }"><i class="bx bx-edit-alt mr-1"></i> Edit </router-link>
                                                                        <a class="dropdown-item" @click="delete_user(row.id)"><i class="bx bx-trash mr-1"></i>Delete</a>
                                                                    </div>
                                                                </div> 
                                                            </th>
                                                        </tr> 
                                                    </tbody>
                                                </table>
                                            </div>
                                            </div>
                                        </div>  
                                    </div>
                                </div>
                            </div>
                        </div>
                    </div>
                </section> 
                <modal width="60%" height="30%" style="padding:50px" name="popup-singel">
                    <i @click="hide_pop()" class="bx bx-x-circle  x-circle"></i>
                    <div class="app-content ">
                       <div class="card">
                          <table class="table table-bordered table-striped table-sm">
                             <tbody> 
                                
                                <tr>
                                   <th class="text-center">
                                      <input class="form-control text-center" v-model="wing_title"  placeholder="Wing Title" >
                                   </th>
                                   <th class="text-center">
                                      <button @click="addWing()" class="btn btn-success">Save</button>
                                   </th>
                                </tr>
                             </tbody>
                          </table>
                       </div>
                    </div>
                 </modal>
            </div>
        </div>
    </div>
    </div> 
</template>
<script>
import { Form } from "vform"; 
import axios from "../../axios_instance";
export default {
  props: { 
  },
  components: {
    // VueRecaptcha, facebookLogin
  },
  data() {
    return {
        base_url: window.base_url,
        api_url: window.api_url, 
        token: this.$localStorage.get("d_token"),
        user: JSON.parse(this.$localStorage.get("user")),
        items:[],  
        status :  '' ,
        dept_id : '',
        WingsItems : [] ,
        WingsUser : [], 
        employeeItem : [],
        wing_title: '',
        wing: new Form({  
            wing_title : '', 
            
        }),
        userChang: new Form({  
            wing_id : '',  
            id : ''  
        }),
         
    };
  },
  created() {  
    this.dept_id = this.user.dept_id ; 
    this.getWing();
    this.getWingsUser();
    this.getEmployee();
  },
  methods: {
    hide_pop() {
        this.$modal.hide("popup-singel");
    },
    show_pop() { 
        this.$modal.show("popup-singel"); 
    },
    async getWing(){ 
        await axios.get(this.api_url + "wings", {
                headers: {
                "Content-Type": "application/json", 
                Authorization: this.token ? `Bearer ${this.token}` : ""
                },
            })
        .then(({ data }) => {  
            this.WingsItems =  data.data ;
            console.log(this.WingsItems );   
        });
    }, 
    async getWingsUser(){ 
        await axios.get(this.api_url + "user_wing", {
                headers: {
                "Content-Type": "application/json", 
                Authorization: this.token ? `Bearer ${this.token}` : ""
                },
            })
        .then(({ data }) => {  
            this.WingsUser =  data.data ;
            console.log(this.WingsUser );   
        });
    }, 
    async getEmployee(){ 
        await axios.get(this.api_url + "users?role_id=7", {
                headers: {
                "Content-Type": "application/json", 
                Authorization: this.token ? `Bearer ${this.token}` : ""
                },
            })
        .then(({ data }) => {  
            this.employeeItem =  data.data ;
            console.log(this.WingsUser );   
        });
    }, 
    changeUser(wing_id){ 
      try {
         let loader = this.$loading.show(); 
         this.userChang.wing_id  =  wing_id ;
         this.userChang.post(this.api_url + "users_change/", {
            headers: {
              "Content-Type": "application/json", 
              Authorization: this.token ? `Bearer ${this.token}` : ""
            },
          }).then((res) => {
              console.log(res);
              if(res.data.success){ 
                  this.getWing();
                   this.$toasted.show(res.data.message, {
                    theme: "bubble",
                    duration: 5000,
                    position: "bottom-right",
                    });
              } 
            loader.hide(); 
            //this.$router.push('/wings');
        },(error)=>{
          console.log(error);
           loader.hide(); 
        })
      } catch (error) {
         // loader.hide(); 
        console.log(error);
      }
    },
    async statusChange(item , status){
        let editForm =  new Form({    
            status: status,
            name : item.name
        })
        try {
         let loader = this.$loading.show();
            editForm.put(this.api_url + "departments/"+ item.id, {
                headers: {
                "Content-Type": "application/json", 
                Authorization: this.token ? `Bearer ${this.token}` : ""
                },
            }).then((res) => {
                console.log(res);
                if(res.data.success){ 
                    this.$toasted.show(res.data.message, {
                        theme: "bubble",
                        duration: 5000,
                        position: "bottom-right",
                        });
                } 
                loader.hide(); 
                this.getItems();
            },(error)=>{
            console.log(error);
            loader.hide(); 
            })
        } catch (error) {
            // loader.hide(); 
            console.log(error);
        }
    }, 
    async delete_wing(id){ 
        let loader = this.$loading.show();
        try {
            await axios
            .delete(this.api_url + "wings/"+id, {
                    headers: {
                    "Content-Type": "application/json", 
                    Authorization: this.token ? `Bearer ${this.token}` : ""
                    },
                })
            .then((res) => {  
                console.log(res);
                    this.$toasted.show(res.data.message, {
                        theme: "bubble",
                        duration: 5000,
                        position: "bottom-right",
                        });
                    this.getWing();
               
                loader.hide();
            });
        } catch (error) {
            loader.hide();
        }
      },
    async delete_user(id){ 
        let loader = this.$loading.show();
        try {
            await axios
            .delete(this.api_url + "users/"+id, {
                    headers: {
                    "Content-Type": "application/json", 
                    Authorization: this.token ? `Bearer ${this.token}` : ""
                    },
                })
            .then((res) => {  
                console.log(res);
                    this.$toasted.show(res.data.message, {
                        theme: "bubble",
                        duration: 5000,
                        position: "bottom-right",
                        });
                    this.getWing();
               
                loader.hide();
            });
        } catch (error) {
            loader.hide();
        }
      },
    async getItems(){
        let loader = this.$loading.show();
        this.getDepartments( this.status ).then(({ data }) => { 
            if(data.success){
                loader.hide();
                this.items =  data.data 
            }else{
                loader.hide(); 
            }
        }); 
    },
    async addWing(){
        try {
         let loader = this.$loading.show();
         this.wing.wing_title =  this.wing_title ;
         this.wing.dept_id =  this.dept_id ;
            this.wing.post(this.api_url + "wings", {
                headers: {
                "Content-Type": "application/json", 
                Authorization: this.token ? `Bearer ${this.token}` : ""
                },
            }).then((res) => {
                console.log(res);
                if(res.data.success){
                    this.wing_title  = '';
                    this.wing.wing_title =  '';
                    this.getWing();
                    this.$toasted.show(res.data.message, {
                        theme: "bubble",
                        duration: 5000,
                        position: "bottom-right",
                        });
                } 
                loader.hide(); 
                this.$router.push('/wings');
            },(error)=>{
            console.log(error);
            loader.hide(); 
            })
        } catch (error) {
            // loader.hide(); 
            console.log(error);
        } 
    } 
},
  computed: {},
};
</script>
